const ssh = $input.first().json;
if (ssh.code !== 0) throw new Error('Backup SSH command failed; inspect execution and target status');
let result;
try { result = JSON.parse(ssh.stdout); } catch { throw new Error('Backup returned invalid JSON'); }
if (result.status !== 'success') throw new Error('Backup failed; inspect target status');
return [{ json: result }];

const result = $('Validate backup result1').first().json;
const capacitySSH = $input.first().json;
let capacity;
try {
  if (capacitySSH.code === 0) {
    const parsed = JSON.parse(capacitySSH.stdout);
    if (parsed.status === 'success') capacity = parsed;
  }
} catch {}

if (result.status !== 'success') throw new Error('Only successful backup results can be announced');

const clean = value => String(value ?? '').replace(/[\r\n\x00-\x1f]/g, ' ').replace(/@/g, '＠').slice(0, 100);
const bytes = value => {
  if (!Number.isFinite(value) || value < 0) return 'unknown';
  const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB'];
  const index = Math.min(Math.floor(Math.log(Math.max(value, 1)) / Math.log(1024)), units.length - 1);
  return (value / 1024 ** index).toFixed(index ? 1 : 0) + ' ' + units[index];
};
const date = value => {
  const parsed = new Date(value);
  if (!Number.isFinite(parsed.getTime())) return 'unknown';
  return parsed.toLocaleString('en-GB', { timeZone: 'Europe/Moscow', hour12: false }) + ' MSK';
};
const apps = Array.isArray(result.apps) ? result.apps : [];
const mode = result.storage_mode || (apps.some(app => app.archive) ? 'archive' : 'restic');
const skipped = result.skipped === true || result.stage === 'skipped';
const lines = [
  skipped ? '⏭ Backup skipped — recent backup already succeeded' : '✅ Backup complete',
  'VPS: ' + clean(result.server_id || 'unknown'),
  'Finished: ' + date($now.toISO()),
];
if (skipped) {
  if (result.last_success_at) lines.push('Last success: ' + date(result.last_success_at * 1000));
  lines.push('No new snapshot was created.');
} else {
  lines.push('Storage: ' + clean(mode));
  lines.push('Apps: ' + apps.length);
  const knownBytes = apps.every(app => Number.isFinite(app.data_added) && app.data_added >= 0);
  const added = apps.reduce((total, app) => total + (Number.isFinite(app.data_added) ? app.data_added : 0), 0);
  lines.push('New data uploaded: ' + (knownBytes ? bytes(added) : 'unknown'));
  for (const app of apps.slice(0, 10)) {
    const state = app.unchanged ? 'unchanged' : 'saved';
    const snapshot = typeof app.archive === 'string' ? app.archive.slice(0, 64) : 'archive';
    lines.push('• ' + clean(app.id).slice(0, 63) + ': ' + state + ' · ' + bytes(app.data_added) + ' · ' + snapshot);
  }
  if (apps.length > 10) lines.push('… ' + (apps.length - 10) + ' more apps; see the execution for details.');
  if (Number.isFinite(result.space?.free_bytes)) lines.push('VPS free space before backup: ' + bytes(result.space.free_bytes));
}
if (typeof result.temporary_files_cleaned === 'boolean') {
  lines.push('Temporary files: ' + (result.temporary_files_cleaned ? 'cleaned' : 'check required'));
}
if (capacity) {
  lines.push('Cloud pool: ' + bytes(capacity.free_bytes) + ' free / ' + bytes(capacity.total_bytes) + ' total');
  if (Number.isFinite(capacity.used_bytes)) lines.push('Cloud used: ' + bytes(capacity.used_bytes));
} else {
  lines.push('Cloud space: unavailable (backup result is unaffected)');
}
lines.push('n8n execution: ' + clean($execution.id));
const message = lines.join('\n');
const escapeHTML = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const server = clean(result.server_id || 'unknown');
const title = skipped ? '⏭ Already backed up' : '✓ Backup complete';
const description = skipped
  ? 'A recent backup already succeeded. No new snapshot was created.'
  : apps.length + (apps.length === 1 ? ' app backed up' : ' apps backed up') + ' · ' + clean(mode);
const fields = [{ name: 'Server', value: server, inline: true }];
const telegram = ['<b>' + escapeHTML(title) + '</b>', '<code>' + escapeHTML(server) + '</code>', '', escapeHTML(description)];

if (skipped && result.last_success_at) {
  const lastSuccess = date(result.last_success_at * 1000);
  fields.push({ name: 'Last successful backup', value: lastSuccess, inline: true });
  telegram.push('', '<b>Last backup</b>  ' + escapeHTML(lastSuccess));
}
if (!skipped) {
  const known = apps.every(app => Number.isFinite(app.data_added) && app.data_added >= 0);
  const uploaded = known ? bytes(apps.reduce((total, app) => total + app.data_added, 0)) : 'unknown';
  fields.push({ name: 'Uploaded', value: uploaded, inline: true });
  const appLines = apps.slice(0, 7).map(app => {
    const id = clean(app.id).slice(0, 63);
    const snapshot = typeof app.archive === 'string' ? app.archive.slice(0, 64) : 'archive';
    return id + ' · ' + (app.unchanged ? 'unchanged' : bytes(app.data_added)) + ' · ' + snapshot;
  });
  if (apps.length > 7) appLines.push('+ ' + (apps.length - 7) + ' more in the execution');
  if (appLines.length) fields.push({ name: 'Applications', value: appLines.join('\n'), inline: false });
  telegram.push('', '<b>Uploaded</b>  ' + escapeHTML(uploaded));
  if (appLines.length) telegram.push('<pre>' + escapeHTML(appLines.join('\n')) + '</pre>');
}
let cloudValue = 'Unavailable · backup result is unaffected';
let telegramCloud = escapeHTML(cloudValue);
if (capacity) {
  const free = bytes(capacity.free_bytes);
  const total = bytes(capacity.total_bytes);
  cloudValue = '**' + free + ' free** of ' + total;
  telegramCloud = '<b>' + escapeHTML(free) + ' free</b> of ' + escapeHTML(total);
  const ratioKnown = Number.isFinite(capacity.total_bytes) && capacity.total_bytes > 0
    && Number.isFinite(capacity.free_bytes) && capacity.free_bytes >= 0
    && capacity.free_bytes <= capacity.total_bytes;
  if (ratioKnown) {
    const usedRatio = 1 - capacity.free_bytes / capacity.total_bytes;
    const filled = Math.round(usedRatio * 12);
    const bar = '■'.repeat(filled) + '□'.repeat(12 - filled);
    const percent = Math.round(usedRatio * 100) + '% used';
    cloudValue += '\n' + bar + '  ' + percent;
    telegramCloud += '\n<code>' + bar + '</code>  ' + percent;
  }
}
fields.push({ name: 'Cloud storage · pool capacity', value: cloudValue, inline: false });
telegram.push('', '<b>Cloud storage</b>', telegramCloud);
let footer = 'VPS Backup · Run #' + clean($execution.id);
if (result.temporary_files_cleaned === true) footer += ' · Temp files cleaned';
if (result.temporary_files_cleaned === false) footer += ' · Check temporary files';
const discordEmbed = {
  title, description, color: skipped ? 5793266 : 3066993,
  fields, footer: { text: footer }, timestamp: $now.toISO(),
};
telegram.push('', '<i>' + escapeHTML(date($now.toISO())) + ' · Run #' + escapeHTML(clean($execution.id)) + '</i>');
const telegramMessage = telegram.join('\n');
return [{ json: { message, telegramMessage, discordEmbed, skipped, server_id: result.server_id } }];
